---@class ClubGVGTestDataProvider
local ClubGVGTestDataProvider = {}


---@param mgr ClubGVGMgr
function ClubGVGTestDataProvider:GenerateDataByInterface(interface, requestData, mgr)
    if interface == Interfaces.OverseaClubGVGHome then
        return self:GenerateHomeData(mgr)

    elseif interface == Interfaces.OverseaClubGVGJoin then
        return self:GenerateJoinData(mgr, requestData)
    elseif interface == Interfaces.OverseaClubGVGMarch then
        return self:GenerateMarchData(mgr, requestData)

    elseif interface == Interfaces.OverseaClubGVGMarchAccelerate then
        return self:GenerateMarchAccelerateData(mgr, requestData)
    elseif interface == Interfaces.OverseaClubGVGAtBuilding then
        return self:GenerateAtBuildingData(mgr, requestData)
    elseif interface == Interfaces.OverseaClubGVGAt then
        return self:GenerateAtData(mgr, requestData)
    elseif interface == Interfaces.OverseaClubGVGRebirth then
        return self:GenerateRebirthData(mgr, requestData)
    elseif interface == Interfaces.OverseaClubGVGRank then
        return self:GenerateRankData(mgr, requestData)
    elseif interface == Interfaces.OverseaClubGVGPlayerRank then
        return self:GeneratePlayerRankData(mgr, requestData)
    elseif interface == Interfaces.OverseaClubGVGClubRecruit then
        return self:GenerateClubRecruitData(mgr, requestData)
    elseif interface == Interfaces.OverseaClubGVGPlayerRecruit then
        return self:GeneratePlayerRecruitData(mgr, requestData)
    elseif interface == Interfaces.OverseaClubGVGReport then
        return self:GenerateReportData(mgr, requestData)
    
    elseif interface == Interfaces.OverseaClubGVGDeath then
        return self:GenerateDeath(mgr, requestData)
    

    end
    
end

