function ClubGVGTestDataProvider:PlayReport(mgr)


    -- local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    -- local playerDojo = playerComp.playerDojo
    -- local serverTime = playerDojo:GetLoginServerTime()
    -- local offset = GameUtils.GetServerTime() - serverTime

    
    local serverTime = 1720091472
    ---@type PlayerDojo
    local playerDojo = GameUtils.GetPlayerDojo()
    playerDojo:UpdateServerTime(serverTime)

    -- local Break = CS.UnityEngine.Debug.Break
    local GVGReport = import("Game.UI.Club.GVG.Test.GVGReport")
    local index = 1
    local maxIndex = #GVGReport

    self.co = CoStart(function() 
        CoYield(1)
        -- serverTime = 1720091472
        local st
        while index < maxIndex do 
            local newIndex
            local reportType
            -- local bid
            for i = index, maxIndex, 1 do
                local reportStr = GVGReport[i]
                local d = table.deserialize(reportStr)
                local reportData = d.DATA.data
                st = reportData.st or reportData[1].st
                st = checkNumber(st)
                -- local realData = reportData.st == nil and reportData[1] or reportData
                -- realData.st = st
                
                if st == serverTime then
                    newIndex = i
                    reportType = checkNumber(reportData.t or reportData[1].t)
                    if reportType >= 6 then
                        -- local bid = checkNumber(reportData.bid or reportData[1].bid)
                        print(table.toString(reportData))

                    end
                    print("reportId--->>>", reportData.id or reportData[1].id)
                    mgr:OnReceiveReport(_, reportData)
                else
                    break
                end
            end

            CoYield(1)
            -- if 1720091531 ~= serverTime then
                if newIndex ~= nil then
                    index = newIndex + 1
                end
                serverTime = serverTime + 1
                
            -- else
            --     break
            -- end
        end
    end)
end

