---@param mgr ClubGVGMgr
function ClubGVGTestDataProvider:GenerateMarchAccelerateData(mgr, requestData)
    local  t = [[ {"t":3,"pid":4090,"cd":5,"mt":1717213657,"id":8,"time":"2024-06-01 11:47:14"}	 ]]
    local data = table.deserialize(t)
    data.pid = self:GetPlayerId()
    local dojo = mgr:GetHomeDojo()
    local marchData = dojo.marchInfo[data.pid]
    -- print(table.toString(dojo.marchInfo), table.toString(marchData))
    local mt = GameUtils.GetServerTime() + (marchData.endTime - GameUtils.GetServerTime()) * 0.5
    data.mt = math.ceil(mt)
    mgr:OnReceiveReport(_, data)

    return {data = {}, errCode = 0}
end
