---@param mgr ClubGVGMgr
function ClubGVGTestDataProvider:GenerateDeath(mgr, requestData)
    local dojo = mgr:GetHomeDojo()
    local jsonStr = [[ [{"t":8,"r":4,"pids":[6496],"rtm":1718098194,"id":946,"time":"2024-06-11 17:28:54"}] ]]
    local t = table.deserialize(jsonStr)
    t[1].pids = {self:GetPlayerId()}
    t[1].rtm = GameUtils.GetServerTime() + 60
    t[1].id = dojo.newReportId + 1
    mgr:OnReceiveReport(_, t) 

    -- local jsonStr = [[ [{"t":9,"r":3,"bids":["10004","40013"],"id":319}] ]]
    -- local t = table.deserialize(jsonStr)
    -- mgr:OnReceiveReport(_, t) 

    local data = {}
    return {data = data, errCode = 0}
end

function ClubGVGTestDataProvider:GetPlayerId()
    return checkNumber(self:GetPlayerDojo().playerId)
end

---@return PlayerDojo
function ClubGVGTestDataProvider:GetPlayerDojo()
    local playerDojo = GameUtils.GetPlayerDojo()
    return playerDojo
end

---@return ClubHomeDojo
function ClubGVGTestDataProvider:GetClubDojo()
    local dojo = ClubUtils.GetClubComp():GetHomeDojo()
    return dojo
end

return ClubGVGTestDataProvider
